/* Généré par scripts/construire-pelvis.js — ne pas modifier à la main.
   Index de recherche de la section Pelvis : une entrée par fiche
   (t : titre, n : nom dans le sommaire, u : adresse depuis pelvis/, c : chapitre, b : En bref,
   s : sections { i : ancre, t : titre, x : texte }). */
window.PelvisRecherche = [{"t":"Radio-anatomie de l'ovaire","n":"Radio-anatomie","u":"ovaire/radio-anatomie.html","c":"Ovaire","b":"l'aspect normal de l'ovaire dépend de l'âge et du moment du cycle. Le reconnaître évite de prendre un follicule ou un corps jaune pour une lésion.","s":[{"i":"situation-et-moyens-de-fixite","t":"Situation et moyens de fixité","x":"Organe intrapéritonéal, dans la fossette ovarienne, en arrière du ligament large, sous les vaisseaux iliaques externes. Ligament suspenseur (lombo-ovarien), qui contient le pédicule ovarien ; ligament utéro-ovarien ; mésovarium. Position variable : l'ovaire peut se trouver dans le cul-de-sac de Douglas ou au-dessus de l'utérus, surtout s'il est augmenté de volume."},{"i":"vascularisation","t":"Vascularisation","x":"Artère ovarienne : naît de l'aorte sous les artères rénales, s'anastomose avec l'artère utérine (double vascularisation). Veine ovarienne : longe le psoas, se draine dans la veine cave inférieure à droite et dans la veine rénale gauche à gauche. Repère pratique : suivre le pédicule ovarien jusqu'à une masse prouve son origine ovarienne ou annexielle."},{"i":"aspect-selon-la-periode","t":"Aspect selon la période","x":"Période · Échographie · IRM Activité génitale, phase folliculaire · Follicules antraux < 10 mm ; un follicule dominant grossit jusqu'à environ 20–25 mm avant l'ovulation · Follicules en hypersignal T2 dans un stroma de signal plus bas Phase lutéale · Corps jaune : kyste à paroi épaisse et festonnée, contenu parfois échogène, vascularisation périphérique annulaire au Doppler · Paroi épaisse qui se rehausse, contenu de signal variable Ménopause · Ovaire petit, homogène, peu ou pas de follicules ; petits kystes simples fréquents · Stroma en hyposignal T2, rares follicules"},{"i":"a-retenir","t":"À retenir","x":"Corps jaune : diamètre < 25 mm ; au-delà, on parle de kyste lutéal hémorragique. Le comptage des follicules antraux se fait à J3 du cycle."},{"i":"pieges","t":"Pièges","x":"Une vascularisation annulaire péri-utérine n'est pas toujours un corps jaune : grossesse extra-utérine, abcès tubo-ovarien, myome sous-séreux pédiculé. Doser les βhCG en cas de doute. Un corps jaune hémorragique peut avoir un contenu échogène hétérogène : ne pas le confondre avec une portion tissulaire, car il n'est pas vascularisé à l'intérieur."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille des deux ovaires, présence de follicules et d'un corps jaune, toute lésion avec sa latéralité, sa taille et son score O-RADS."}]},{"t":"Kystes fonctionnels","n":"Kystes fonctionnels","u":"ovaire/kystes-fonctionnels.html","c":"Ovaire","b":"chez la femme non ménopausée, un kyste uniloculaire à paroi fine est presque toujours fonctionnel et régresse spontanément en quelques semaines.","s":[{"i":"terrain","t":"Terrain","x":"Femme en période d'activité génitale. Un kyste hémorragique après la ménopause est inhabituel et doit faire reconsidérer le diagnostic."},{"i":"imagerie","t":"Imagerie","x":"Kyste folliculaire (follicule dominant qui ne s'est pas rompu) Échographie : kyste uniloculaire, anéchogène, paroi fine, renforcement postérieur, sans cloison ni végétation. IRM : franc hypersignal T2, hyposignal T1, paroi fine. Corps jaune et kyste lutéal hémorragique (saignement dans un corps jaune ; kyste lutéal hémorragique au-delà de 25 mm) Échographie : contenu échogène hétérogène en « filet de pêche » (cloisons de fibrine mobiles et avasculaires), parfois caillot aux bords concaves ; couronne d'hypervascularisation en Doppler. IRM : iso- ou hypersignal T1 inférieur à la graisse (contrairement à l'endométriome), signal T2 variable ; hypervascularisation annulaire périphérique (rehaussement pariétal, hypersignal diffusion de la paroi)."},{"i":"signes-cles","t":"Signes clés","x":"Un caillot se déforme sous la sonde, n'est pas vascularisé et a des bords concaves ; une végétation est convexe et peut être vascularisée. Le kyste hémorragique évolue en quelques semaines : son aspect change au contrôle."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste à contenu échogène : endométriome, tératome mature, abcès tubo-ovarien, tumeur mucineuse. Kyste simple qui persiste : cystadénome séreux ; aucun signe d'imagerie ne le distingue d'un kyste folliculaire, seule l'évolution le fait. Kyste para-ovarien ou para-tubaire : kyste simple séparé de l'ovaire, qui bouge indépendamment de lui sous la sonde (O-RADS 2, pas de surveillance)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Situation · Conduite Kyste liquidien pur, femme non ménopausée · Kyste fonctionnel entre 3 et 5 cm : contrôle échographique optionnel à 6–12 semaines Kyste liquidien pur, femme ménopausée · À considérer comme une lésion organique au-delà de 1 cm Kyste liquidien pur > 7 cm · IRM Kyste lutéal hémorragique < 5 cm · Pas de contrôle Kyste lutéal hémorragique > 5 cm · Contrôle échographique éventuel à 6–12 semaines"},{"i":"pieges","t":"Pièges","x":"Ne pas décrire comme « portion tissulaire » un caillot ou un réseau de fibrine non vascularisés. Aucun critère d'imagerie ne distingue un kyste folliculaire d'un cystadénome séreux bénin : seule la régression spontanée tranche."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, contenu, paroi, absence de portion tissulaire et de flux interne, statut ménopausique et conduite proposée."}]},{"t":"Rupture et hémorragie de kyste","n":"Rupture et hémorragie de kyste","u":"ovaire/rupture-hemorragie-kyste.html","c":"Ovaire","b":"douleur pelvienne aiguë + kyste ovarien + épanchement : on juge la gravité sur l'abondance de l'hémopéritoine, après avoir éliminé une grossesse extra-utérine.","s":[{"i":"terrain","t":"Terrain","x":"Femme jeune, souvent en deuxième partie de cycle (corps jaune) ; facteurs favorisants : rapport sexuel, traumatisme, anticoagulants."},{"i":"imagerie","t":"Imagerie","x":"Hémorragie intrakystique Kyste sous tension, douloureux au passage de la sonde, contenu échogène hétérogène proche de celui du kyste lutéal hémorragique. Fissure Kyste affaissé aux contours irréguliers, épanchement échogène de faible abondance dans le cul-de-sac de Douglas. Rupture Saignement d'un vaisseau de la paroi du kyste : hémopéritoine abondant qui remonte dans les gouttières et l'espace de Morison. Scanner : liquide de densité élevée ; caillot sentinelle plus dense au contact de l'ovaire qui saigne ; extravasation de contraste en cas de saignement actif."},{"i":"signes-cles","t":"Signes clés","x":"Caillot sentinelle = localisation de la source du saignement. Triade : kyste ovarien + hémopéritoine + βhCG négatifs."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Grossesse extra-utérine rompue : à éliminer en premier (βhCG). Torsion d'annexe, salpingite, appendicite."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Hémopéritoine modéré et patiente stable : surveillance médicale. Hémopéritoine abondant, instabilité hémodynamique ou extravasation active : chirurgie en urgence (ou embolisation selon le contexte)."},{"i":"pieges","t":"Pièges","x":"Un épanchement de faible abondance dans le Douglas peut être physiologique ; c'est son caractère échogène et son abondance qui orientent. Ne jamais conclure à une rupture de kyste avant d'avoir le résultat des βhCG."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté et aspect du kyste, abondance et extension de l'hémopéritoine (Douglas seul, gouttières, Morison), caillot sentinelle, saignement actif."}]},{"t":"Torsion d'annexe","n":"Torsion d'annexe","u":"ovaire/torsion-annexe.html","c":"Ovaire","b":"urgence chirurgicale dont le diagnostic repose sur la morphologie. Un flux Doppler conservé ne l'élimine pas.","s":[{"i":"terrain","t":"Terrain","x":"Femme jeune, enfant, grossesse, stimulation ovarienne. Souvent sur un ovaire augmenté de volume : kyste, tératome mature, ovaires stimulés. Possible sur un ovaire normal, surtout chez l'enfant. Douleur pelvienne brutale, nausées, vomissements."},{"i":"imagerie","t":"Imagerie","x":"Échographie (examen de première intention) Ovaire augmenté de volume, nettement plus gros que le controlatéral, stroma œdématié, follicules refoulés en périphérie. Médialisation de l'ovaire : en position médiane, dans le Douglas ou au-dessus de l'utérus. Tour de spire et épaississement du pédicule ovarien, en cible ou en tourbillon au Doppler. Épanchement libre. Scanner Ovaire augmenté, utérus dévié du côté de la torsion, trompe épaissie, infiltration de la graisse, ascite ; défaut de rehaussement si nécrose. IRM Hypersignal T1 du stroma ou de la paroi en saturation de graisse = infarcissement hémorragique. Absence de rehaussement = nécrose."},{"i":"signes-cles","t":"Signes clés","x":"Tour de spire du pédicule : signe le plus spécifique. Douleur aiguë + tératome ou gros kyste = torsion jusqu'à preuve du contraire."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Rupture ou hémorragie de kyste, grossesse extra-utérine, abcès tubo-ovarien, appendicite. Œdème ovarien massif : peut correspondre à une torsion partielle ou intermittente. Torsion tubaire isolée : ovaire normal, trompe dilatée et tordue."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Avis chirurgical urgent : cœlioscopie avec détorsion et conservation de l'ovaire autant que possible, même s'il paraît nécrosé."},{"i":"pieges","t":"Pièges","x":"Doppler normal : la double vascularisation (artères ovarienne et utérine) et la torsion intermittente gardent souvent un flux. Torsion sur ovaire normal chez l'enfant : pas de masse pour attirer l'attention."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et position de l'ovaire, tour de spire, flux Doppler, masse sous-jacente, épanchement, signes de nécrose en IRM ou au scanner."}]},{"t":"Syndrome des ovaires polykystiques","n":"SOPK","u":"ovaire/sopk.html","c":"Ovaire","b":"le SOPK est un diagnostic clinique, biologique et échographique. L'échographie n'apporte qu'un des trois critères : plus de 25 follicules par ovaire et des ovaires augmentés de surface ou de volume.","s":[{"i":"terrain","t":"Terrain","x":"Femme en âge de procréer ; trouble endocrinien fréquent. Troubles du cycle, hyperandrogénie (hirsutisme, acné), infertilité."},{"i":"criteres-diagnostiques","t":"Critères diagnostiques","x":"Au moins 2 critères sur 3, après exclusion des autres causes : Dysovulation ou anovulation. Hyperandrogénie clinique ou biologique. Ovaires polykystiques à l'échographie."},{"i":"ovaires-polykystiques-a-l-echographie-sopk","t":"Ovaires polykystiques à l'échographie (≠ SOPK)","x":"Deux critères échographiques réunis : Surface ovarienne > 5,5 cm² (ou somme des deux surfaces > 11 cm²), ou volume ovarien > 10 cm³. Comptage folliculaire > 25 par ovaire, follicules < 10 mm. Mesure en l'absence de corps jaune, comptage à J3 du cycle."},{"i":"imagerie","t":"Imagerie","x":"Échographie : augmentation de volume bilatérale des ovaires, follicules en répartition périphérique, hypertrophie du stroma ovarien. IRM (non indiquée pour le diagnostic) : follicules en hypersignal T2 en périphérie, stroma central en hyposignal T2."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Ovaires multifolliculaires de l'adolescente ou de l'hypogonadisme : follicules répartis dans tout l'ovaire, sans stroma abondant. Hyperthécose : hyperandrogénie plus marquée, stroma solide."},{"i":"pieges","t":"Pièges","x":"Pas d'échographie pour ce diagnostic dans les 8 ans qui suivent les premières règles : les ovaires multifolliculaires sont normaux à cet âge. Ne pas compter un corps jaune ou un follicule dominant parmi les follicules antraux. Une échographie évocatrice ne suffit pas : sans les critères cliniques ou biologiques, ce n'est pas un SOPK."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Voie d'abord, nombre de follicules par ovaire, volume des deux ovaires, absence de follicule dominant, de corps jaune ou de kyste au moment de la mesure."}]},{"t":"Lésions pseudotumorales de l'ovaire","n":"Lésions pseudotumorales","u":"ovaire/lesions-pseudotumorales.html","c":"Ovaire","b":"ces lésions non tumorales gardent l'architecture de l'ovaire, avec des follicules refoulés en périphérie. Le contexte (âge, hormones, chirurgie, torsion) fait le diagnostic.","s":[{"i":"dystrophie-macro-antrale","t":"Dystrophie macro-antrale","x":"Contexte inflammatoire pelvien : antécédent de chirurgie ou d'infection, endométriose, adhérences. Ovaire souvent unilatéral, augmenté de volume, contours polycycliques, macro-kystes à paroi fine (1,5 à 8 cm), pseudo-kystes péritonéaux associés. Diagnostic différentiel : tumeur multiloculaire (mucineuse, séreuse, granulosa). Une surveillance rapprochée tranche."},{"i":"lesions-stromales","t":"Lésions stromales","x":"Entité · Terrain · Imagerie · Point clé Œdème ovarien massif · Femme jeune, douleur pelvienne · Unilatéral dans 90 % des cas, ovaire augmenté, franc hypersignal T2 du stroma, follicules en périphérie, peu vascularisé · Unilatéral : chercher une torsion partielle ou intermittente. Bilatéral : chercher des métastases (gastriques surtout) Fibromatose ovarienne · Femme jeune, antécédent de torsion ou de chirurgie · Unilatérale dans 80 % des cas, plages fibreuses mal limitées autour des follicules, franc hyposignal T2, hyposignal diffusion, rehaussement faible · Stade évolué de l'œdème ; le fibrome est, lui, une masse bien limitée Hyperplasie stromale · Femme ménopausée · Bilatérale, épaississement stromal en hyposignal T2, sans hypersignal diffusion, rehaussement faible et progressif · Associée à une hyperandrogénie ou à un cancer de l'endomètre Hyperthécose · Surtout après la ménopause, plus rarement avant · Bilatérale, ovaires augmentés et arrondis, stroma solide en hyposignal T2, rehaussement faible · Hyperandrogénie marquée, parfois virilisation"},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Métastases solides bilatérales (sein lobulaire, estomac) : signal T2 intermédiaire, hypersignal diffusion, rehaussement plus franc (courbe de type 2). Tumeur sécrétante d'androgènes (Sertoli-Leydig, tumeur à cellules stéroïdes) : masse focale unilatérale."},{"i":"pieges","t":"Pièges","x":"Œdème ovarien massif et torsion se recouvrent : un gros ovaire œdématié et douloureux impose de chercher un tour de spire. L'hyperthécose et l'hyperplasie stromale se ressemblent beaucoup en imagerie ; seule l'histologie les distingue formellement."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Uni- ou bilatéralité, taille des ovaires, répartition des follicules, signal T2 et diffusion du stroma, signes de torsion, endomètre (épaissi ou non)."}]},{"t":"Hyperstimulation ovarienne","n":"Hyperstimulation ovarienne","u":"ovaire/hyperstimulation-ovarienne.html","c":"Ovaire","b":"deux gros ovaires multikystiques, symétriques, sans portion solide, dans un contexte de stimulation ou de grossesse. La gravité se juge sur l'ascite, l'épanchement pleural et la taille des ovaires.","s":[{"i":"terrain","t":"Terrain","x":"Exogène : après traitement inducteur de l'ovulation (procréation médicalement assistée). Endogène : grossesse avec hCG élevée (grossesse multiple, môle) ; on parle d'hyperreactio luteinalis ou de kystes lutéiniques."},{"i":"imagerie","t":"Imagerie","x":"Ovaires bilatéraux et symétriques, très augmentés de volume, multikystiques, loculi de taille similaire. Kystes à paroi fine, parfois hémorragiques, sans portion solide ni végétation. Ascite, épanchement pleural dans les formes graves."},{"i":"gravite-reperes-usuels","t":"Gravité (repères usuels)","x":"Forme · Taille des ovaires · Signes associés Légère · < 8 cm · Douleur et ballonnement modérés Modérée · 8 à 12 cm · Ascite visible en échographie Sévère · > 12 cm · Ascite clinique, épanchement pleural, troubles hydro-électrolytiques"},{"i":"complications","t":"Complications","x":"Torsion d'annexe, rupture ou hémorragie de kyste, thromboses veineuses et artérielles."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Tumeur ovarienne multiloculaire (mucineuse, séreuse, granulosa) : habituellement unilatérale, hors de ce contexte."},{"i":"pieges","t":"Pièges","x":"Ne pas proposer de chirurgie pour ces ovaires : ils régressent avec la baisse de l'hCG. Une douleur brutale sur des ovaires stimulés doit faire chercher une torsion."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille des deux ovaires, aspect des kystes, ascite (abondance), épanchement pleural, signes de torsion ou de thrombose."}]},{"t":"Démarche devant une masse annexielle","n":"Démarche devant une masse","u":"ovaire/demarche-masse-annexielle.html","c":"Ovaire","b":"l'échographie trie, l'IRM caractérise ce qui reste indéterminé, le scanner sert au bilan d'extension. La question centrale est l'existence d'une portion tissulaire et son comportement.","s":[{"i":"","t":"","x":"Sans portion tissulaire, ou avec un tissu en hyposignal T2 et en diffusion, la masse reste à faible risque ; sinon, c'est la courbe de rehaussement qui fixe le score."},{"i":"etape-1-la-masse-est-elle-ovarienne","t":"Étape 1 : la masse est-elle ovarienne ?","x":"Pour une origine ovarienne : croissant ovarien péri-lésionnel, pédicule ovarien qui mène à la masse, ovaire homolatéral non vu séparément. Origines à éliminer : myome sous-séreux pédiculé (vaisseaux qui le relient à l'utérus, signal du myomètre), trompe (hydrosalpinx, pyosalpinx), kyste para-ovarien, pseudo-kyste péritonéal, lésion digestive, adénopathie."},{"i":"etape-2-quel-est-le-contenu","t":"Étape 2 : quel est le contenu ?","x":"Contenu · Indice d'imagerie · Lésions évoquées Liquide pur · Anéchogène ; hypersignal T2, hyposignal T1 · Kyste folliculaire, cystadénome séreux, kyste para-ovarien Graisse · Hyperéchogène avec cône d'ombre ; hypersignal T1 qui chute en saturation de graisse · Tératome mature Sang · Contenu échogène finement piqueté ou en « filet de pêche » ; hypersignal T1 qui persiste en saturation de graisse · Endométriome (hypersignal T1 ≥ graisse, shading T2), kyste lutéal hémorragique (hypersignal T1 < graisse) Mucine · Loculi de signaux différents · Tumeur mucineuse Tissu · Composante qui se rehausse · Tumeur à caractériser"},{"i":"etape-3-analyser-la-portion-tissulaire","t":"Étape 3 : analyser la portion tissulaire","x":"Portion tissulaire = ce qui se rehausse : végétation, nodule mural, cloison irrégulière ou épaisse, masse solide. Débris, caillots et phanères ne se rehaussent pas. Paroi et cloisons fines et régulières qui se rehaussent ne comptent pas. En IRM : signal T2 et diffusion comparés au myomètre externe, puis courbe de rehaussement dynamique comparée au myomètre externe. Tissu en hyposignal T2 franc ET en hyposignal en diffusion haute valeur de b = bénin (fibrome, fibrothécome, Brenner, cystadénofibrome)."},{"i":"etape-4-chercher-les-signes-d-extension","t":"Étape 4 : chercher les signes d'extension","x":"Ascite (au-delà d'une lame physiologique du Douglas), carcinose péritonéale, adénopathies, lésions bilatérales. Masses bilatérales solides ou mucineuses : penser aux métastases et chercher un primitif (digestif, sein)."},{"i":"protocole-irm-d-une-masse-annexielle","t":"Protocole IRM d'une masse annexielle","x":"T2 dans au moins deux plans, avec un axial étendu jusqu'aux hiles rénaux. T1 sans et avec saturation de la graisse. Diffusion axiale avec une valeur de b ≥ 1000. T1 dynamique après injection (résolution temporelle ≤ 15 s), puis T1 tardif avec saturation de la graisse. Indications : masse pelvienne indéterminée ou complexe, masse > 7 cm, masse avec végétation, mixte ou solide."},{"i":"pieges","t":"Pièges","x":"La diffusion n'est pas interprétable dans une zone en hypersignal T1 (sang, graisse). Le croissant ovarien autour d'une lésion est un argument d'origine, pas de bénignité."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Origine de la masse, taille, contenu, portion tissulaire (taille, signal T2, diffusion, courbe), signes d'extension, score O-RADS."}]},{"t":"O-RADS échographie","n":"O-RADS échographie","u":"ovaire/o-rads-echographie.html","c":"Ovaire","b":"O-RADS échographie (version 2022) classe une masse annexielle de 0 à 5 selon sa morphologie, sa taille et sa vascularisation. Le score couleur (SC) va de 1 (pas de flux) à 4 (flux très abondant).","s":[{"i":"definitions","t":"Définitions","x":"Portion tissulaire : composante vascularisée ou rehaussée. Les débris, caillots et phanères n'en sont pas. Végétation (projection papillaire) : portion tissulaire d'au moins 3 mm de hauteur, née de la paroi ou d'une cloison, qui fait saillie dans le kyste. Paroi ou cloison irrégulière : irrégularité de moins de 3 mm de hauteur. Lésion solide : au moins 80 % de tissu. Ascite : en dehors d'une petite lame physiologique du cul-de-sac de Douglas, et sans autre cause."},{"i":"categories","t":"Catégories","x":"O-RADS · Risque de malignité · Critères principaux · Conduite 0 · Non évaluable · Examen techniquement incomplet · Nouvelle échographie ou IRM 1 · Ovaire normal · Follicule ou corps jaune ≤ 3 cm chez la femme non ménopausée · Aucune 2 · < 1 % · Kyste simple < 10 cm ; kyste uniloculaire non simple ou biloculaire à paroi lisse < 10 cm ; lésion bénigne typique < 10 cm (kyste hémorragique, kyste dermoïde, endométriome) ; kyste para-ovarien, pseudo-kyste péritonéal, hydrosalpinx typiques · Suivi selon la taille et le statut ménopausique 3 · 1 à < 10 % · Kyste uni- ou biloculaire lisse ≥ 10 cm ; lésion bénigne typique ≥ 10 cm ; kyste uniloculaire irrégulier ; kyste multiloculaire lisse < 10 cm, SC < 4 ; lésion solide lisse SC 1 ; lésion solide lisse avec atténuation postérieure, SC 2–3 · Avis gynécologique ; échographiste référent ou IRM 4 · 10 à < 50 % · Kyste uniloculaire avec 1 à 3 végétations ou une portion tissulaire ; kyste bi- ou multiloculaire avec portion tissulaire, SC 1–2 ; kyste multiloculaire sans portion tissulaire ≥ 10 cm, ou SC 4, ou à paroi ou cloisons irrégulières ; kyste biloculaire irrégulier ; lésion solide lisse sans atténuation postérieure, SC 2–3 · IRM ou échographiste référent ; gynécologue avec avis oncologique 5 · ≥ 50 % · Kyste uniloculaire avec ≥ 4 végétations ; kyste bi- ou multiloculaire avec portion tissulaire, SC 3–4 ; lésion solide lisse SC 4 ; lésion solide à contours irréguliers ; ascite et/ou nodules péritonéaux · Gynécologue oncologue"},{"i":"lesions-benignes-typiques-o-rads-2","t":"Lésions bénignes typiques (O-RADS 2)","x":"Lésion · Aspect typique · Suivi Kyste hémorragique · Uniloculaire, contenu en « filet de pêche » ou caillot, sans flux interne · Non ménopausée ≤ 5 cm : aucun ; > 5 cm : contrôle à 2–3 mois ; ménopausée : contrôle à 2–3 mois ou IRM Kyste dermoïde · ≤ 3 loculi, sans flux, zone hyperéchogène avec atténuation postérieure, lignes et points hyperéchogènes, sphères flottantes · Contrôle à 12 mois s'il n'est pas opéré Endométriome · ≤ 3 loculi, sans flux, contenu échogène homogène finement piqueté, ± petits foyers échogènes pariétaux · Non ménopausée : contrôle à 12 mois s'il n'est pas opéré ; ménopausée : contrôle à 2–3 mois ou IRM Kyste para-ovarien · Kyste simple séparé de l'ovaire · Aucun Pseudo-kyste péritonéal · Collection qui épouse les organes, ovaire en bordure ou suspendu, ± cloisons · Aucun en imagerie Hydrosalpinx · Structure tubulaire anéchogène, cloisons incomplètes, plis muqueux · Aucun en imagerie"},{"i":"pieges","t":"Pièges","x":"Le score s'applique aux patientes à risque moyen et sans symptôme aigu. Un caillot ou des phanères ne sont pas une portion tissulaire : vérifier l'absence de flux."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, nombre de loculi, contours, portion tissulaire et végétations (nombre), score couleur, ascite, catégorie O-RADS et conduite proposée."}]},{"t":"O-RADS IRM","n":"O-RADS IRM","u":"ovaire/o-rads-irm.html","c":"Ovaire","b":"le score O-RADS IRM classe en 5 catégories de risque les masses annexielles complexes ou indéterminées en échographie. Tout repose sur la portion tissulaire et sa courbe de rehaussement, comparée au myomètre externe.","s":[{"i":"protocole","t":"Protocole","x":"T2 dans deux plans au moins, axial jusqu'aux hiles rénaux. T1 sans et avec saturation de la graisse. Diffusion axiale, b ≥ 1000. T1 dynamique après injection (résolution temporelle ≤ 15 s), puis T1 tardif avec saturation de la graisse."},{"i":"definitions","t":"Définitions","x":"Portion tissulaire : toujours rehaussée ; végétation, nodule mural, cloison irrégulière ou lésion purement solide. Portion tissulaire en hyposignal T2 franc ET en hyposignal diffusion : en faveur de la bénignité (score 2), sans analyse de la courbe."},{"i":"courbes-de-rehaussement-par-rapport-au-myometre-externe","t":"Courbes de rehaussement (par rapport au myomètre externe)","x":"Courbe · Forme · Risque Type 1 · Montée progressive, sans épaulement · Faible Type 2 · Montée initiale moins rapide que le myomètre, puis plateau · Intermédiaire Type 3 · Montée initiale plus rapide que le myomètre · Élevé Sans séquence dynamique : rehaussement de la portion tissulaire ≤ myomètre à 30–40 s = score 4 ; > myomètre = score 5."},{"i":"scores","t":"Scores","x":"Score · Valeur prédictive positive · Critères 0 · Non évaluable · Examen incomplet 1 · Ovaire normal · Pas de lésion ; follicule, kyste hémorragique ou corps jaune ≤ 3 cm chez la femme non ménopausée 2 · < 0,5 % · Kyste uniloculaire sans rehaussement pariétal ; kyste uniloculaire à contenu liquidien pur ou endométriosique, paroi lisse rehaussée ; lésion graisseuse sans portion tissulaire ; portion tissulaire en hyposignal T2 franc et en hyposignal diffusion ; trompe dilatée à contenu liquidien pur et paroi fine ; kyste para-ovarien 3 · ≈ 5 % · Kyste uniloculaire à contenu protéique, hémorragique ou mucineux, paroi lisse rehaussée ; kyste multiloculaire sans graisse, cloisons et paroi lisses, sans portion tissulaire ; portion tissulaire avec courbe de type 1 ; trompe dilatée à contenu non liquidien pur ou à paroi épaisse et lisse 4 · ≈ 50 % · Portion tissulaire avec courbe de type 2 ; lésion graisseuse avec une portion tissulaire volumineuse 5 · ≈ 90 % · Portion tissulaire avec courbe de type 3 ; nodules ou épaississement irrégulier du péritoine, du mésentère ou de l'épiploon, avec ou sans ascite"},{"i":"pieges","t":"Pièges","x":"La protubérance de Rokitansky d'un kyste dermoïde peut se rehausser un peu sans faire passer en score 4 : il faut une portion tissulaire volumineuse. La diffusion n'est pas interprétable dans une zone en hypersignal T1. Une courbe de type 3 n'est pas toujours maligne : goitre ovarien, tumeur stromale sclérosante."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Origine, taille, contenu (signal T1, T1 FS, T2), portion tissulaire (taille, signal T2, diffusion, type de courbe), péritoine, score O-RADS IRM."}]},{"t":"Tumeurs épithéliales séreuses","n":"Tumeurs épithéliales séreuses","u":"ovaire/tumeurs-epitheliales-sereuses.html","c":"Ovaire","b":"les végétations signent une tumeur épithéliale, pas la malignité. C'est leur nombre, leur taille, leur siège et leur comportement en IRM qui séparent bénin, frontière et malin.","s":[{"i":"terrain","t":"Terrain","x":"Tumeurs épithéliales les plus fréquentes, environ 30 % des tumeurs ovariennes ; à tout âge. Environ 70 % bénignes, 5 à 10 % frontières, 20 à 25 % malignes."},{"i":"imagerie","t":"Imagerie","x":"Forme · Aspect · Portion tissulaire  · xKyste uniloculaire, rond, liquidien pur, paroi fine non vascularisée ; bilatéral dans 7 à 20 % des cas ; calcosphérites possibles · Aucune Cystadénome séreux bénin papillaire · Masse à prédominance kystique · Végétations peu nombreuses, endokystiques, < 1 cm, non vascularisées au Doppler ; hyposignal T2, hyposignal diffusion, courbe de type 1 Cystadénome séreux frontière · Masse à prédominance kystique, unilatérale (66 %), uni- ou multiloculaire · Végétations nombreuses, confluentes, > 1 cm, endo- et/ou exokystiques, flux central au Doppler ; signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 ; implants péritonéaux et ganglionnaires possibles Cystadénocarcinome séreux · Masse mixte ou à prédominance kystique, bilatérale (66 %) · Portions tissulaires irrégulières et végétations vascularisées ; T2 intermédiaire, hypersignal diffusion, courbe de type 2 ou 3 ; carcinose péritonéale, adénopathies"},{"i":"signes-cles","t":"Signes clés","x":"Végétation exokystique = tumeur frontière jusqu'à preuve du contraire. Calcifications de la tumeur, des ganglions ou de la carcinose : plutôt cystadénocarcinome de bas grade. Le cystadénocarcinome séreux est le plus fréquent des carcinomes ovariens (60 %), de haut grade dans 95 % des cas et découvert à un stade avancé dans 80 % des cas."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste folliculaire (≥ 3 cm, femme non ménopausée) : régresse en 6 à 12 semaines ; aucun critère d'imagerie ne le distingue d'un cystadénome séreux. Kyste d'inclusion corticale : femme ménopausée, < 1 cm. Lésions extra-ovariennes (kyste para-ovarien, hydrosalpinx) : pas de croissant ovarien. Lésions mixtes bilatérales : éliminer des métastases ovariennes et chercher un cancer primitif (digestif, sein)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Kyste liquidien pur : femme non ménopausée, kyste fonctionnel entre 3 et 5 cm (contrôle optionnel à 6–12 semaines) ; femme ménopausée, lésion organique au-delà de 1 cm ; IRM si > 7 cm. Végétations ou portion tissulaire : IRM avec score O-RADS IRM, puis avis gynécologique ou oncologique. Suspicion de carcinome : scanner thoraco-abdomino-pelvien pour la cartographie de la carcinose."},{"i":"pieges","t":"Pièges","x":"Des végétations en hyposignal T2 et hyposignal diffusion avec une courbe de type 1 sont en faveur d'un cystadénome papillaire bénin. Le cystadénome séreux frontière peut donner des implants péritonéaux : ce n'est pas forcément un carcinome."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Latéralité, taille, nombre de loculi, végétations (nombre, taille, siège endo- ou exokystique, signal, courbe), ascite, carcinose, adénopathies."}]},{"t":"Tumeurs épithéliales mucineuses","n":"Tumeurs épithéliales mucineuses","u":"ovaire/tumeurs-epitheliales-mucineuses.html","c":"Ovaire","b":"volumineuse masse multiloculaire, unilatérale, aux loculi de signaux différents. Une tumeur mucineuse bilatérale est une métastase d'origine digestive jusqu'à preuve du contraire.","s":[{"i":"terrain","t":"Terrain","x":"10 à 15 % des tumeurs ovariennes, femme de 20 à 50 ans. Continuum lésionnel : environ 80 % bénignes, 16 à 17 % frontières, moins de 5 % malignes."},{"i":"imagerie","t":"Imagerie","x":"Masse à prédominance kystique, volumineuse (10 à 15 cm), unilatérale (95 %). Multiloculaire, avec des loculi de signaux différents en T1 et en T2 (mucine plus ou moins concentrée). Forme · Cloisons et portion tissulaire Tumeur mucineuse bénigne · Cloisons fines, peu nombreuses, régulières Tumeur mucineuse frontière · Cloisons irrégulières, nombreuses, regroupées ; microvégétations en hyposignal T2, < 3 mm Tumeur mucineuse invasive · Cloisons irrégulières et épaisses et/ou nodule tissulaire en signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 (plus rarement de type 3)"},{"i":"signes-cles","t":"Signes clés","x":"Le regroupement des cloisons et les microvégétations orientent vers une tumeur frontière. Tumeur mucineuse + épanchement intra-abdominal : suspecter une rupture et un pseudomyxome péritonéal."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Métastases ovariennes d'un cancer digestif (côlon, appendice, estomac, pancréas) : bilatérales. Dystrophie macro-antrale, tumeur de la granulosa, tumeur séreuse multiloculaire. Associations lésionnelles possibles sur le même ovaire : tumeur de Brenner, kyste dermoïde."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"IRM avec score O-RADS IRM ; chirurgie, avec avis oncologique en cas de cloisons irrégulières ou de nodule. Bilatéralité ou pseudomyxome : chercher un cancer digestif, en premier lieu appendiculaire."},{"i":"pieges","t":"Pièges","x":"Ne pas conclure à une tumeur mucineuse primitive devant des lésions bilatérales. La taille de la masse ne préjuge pas de sa malignité : seules les cloisons et la portion tissulaire comptent."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, latéralité, nombre et signal des loculi, épaisseur et regroupement des cloisons, microvégétations ou nodule (signal, diffusion, courbe), épanchement, appendice."}]},{"t":"Cystadénofibrome et tumeur de Brenner","n":"Cystadénofibrome et tumeur de Brenner","u":"ovaire/cystadenofibrome-brenner.html","c":"Ovaire","b":"deux tumeurs épithéliales bénignes dont la portion tissulaire fibreuse est en hyposignal T2 franc et en hyposignal diffusion. Elles ne doivent pas être prises pour des cancers.","s":[{"i":"cystadenofibrome","t":"Cystadénofibrome","x":"Définition : tumeur séreuse bénigne avec une portion fibromateuse prédominante (cystadénofibrome) ou quasi exclusive (adénofibrome). Masse à prédominance kystique, plus rarement solide ; bilatérale plus souvent qu'unilatérale ; multiloculaire plus souvent qu'uniloculaire. Portion tissulaire : cloisons épaisses souvent irrégulières, végétations, nodule mural (56 %). Portion tissulaire en hyposignal T2 franc et hyposignal diffusion, courbe de type 1 (rarement de type 2) : score O-RADS IRM 2. Diagnostic différentiel : cystadénome séreux associé à un fibrome ovarien."},{"i":"tumeur-de-brenner","t":"Tumeur de Brenner","x":"Définition : tumeur épithéliale à cellules transitionnelles (différenciation urothéliale). Rare (1 à 2 % des tumeurs ovariennes), bénigne dans 95 % des cas. Unilatérale (94 %), bien limitée, petite (souvent ≤ 2 cm), solide pure. Échographie : isoéchogène au myomètre, atténuation postérieure, faible vascularisation centrale. IRM : hyposignal T2 franc, diffusion variable, courbe de type 2. Calcifications centrales punctiformes dans 50 % des cas. Associations lésionnelles : kyste dermoïde, tumeur mucineuse."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Fibrome ovarien : courbe de type 1. Myome sous-séreux pédiculé : extra-ovarien, raccordé au myomètre, encorbellement vasculaire au Doppler, souvent d'autres myomes."},{"i":"pieges","t":"Pièges","x":"Une portion tissulaire épaisse et irrégulière inquiète en échographie : l'IRM la reclasse si elle est en hyposignal T2 franc et en hyposignal diffusion. Une tumeur de Brenner peut accompagner une tumeur mucineuse : analyser séparément chaque composante."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Signal T2 et diffusion de la portion tissulaire, type de courbe, calcifications, lésion associée, score O-RADS IRM."}]},{"t":"Carcinomes endométrioïde et à cellules claires","n":"Carcinomes endométrioïde et à cellules claires","u":"ovaire/endometrioide-cellules-claires.html","c":"Ovaire","b":"ces carcinomes naissent souvent sur une endométriose. Une portion tissulaire vascularisée dans un endométriome doit faire évoquer une transformation maligne.","s":[{"i":"terrain","t":"Terrain","x":"Association à l'endométriose : 40 % pour le carcinome endométrioïde, 70 % pour le carcinome à cellules claires. Femme plus jeune que pour les autres tumeurs épithéliales malignes, endométriose souvent connue. Carcinome endométrioïde ovarien associé à un cancer de l'endomètre dans 20 % des cas."},{"i":"imagerie","t":"Imagerie","x":"Masse mixte, unilatérale plus souvent que bilatérale, parfois développée sur un endométriome. Endométriose pelvienne associée fréquente. Portions tissulaires en signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 ou 3. Remaniements hémorragiques plus fréquents dans le carcinome endométrioïde."},{"i":"transformation-maligne-d-un-endometriome","t":"Transformation maligne d'un endométriome","x":"Critères de suspicion Taille > 10 cm. Asymétrie de taille par rapport aux autres endométriomes. Apparition d'une portion tissulaire. Imagerie Échographie : végétations ou nodules solides vascularisés au Doppler. IRM : portion tissulaire en hyposignal T1, signal T2 variable, hypersignal diffusion ; les images de soustraction aident à voir le rehaussement dans un kyste en hypersignal T1. Végétation + courbe de type 2 → tumeur frontière ; nodule solide + courbe de type 2 ou 3 → tumeur invasive."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Endométriome décidualisé pendant la grossesse : portion tissulaire vascularisée en hypersignal T2 franc, sans progression pendant la grossesse, disparition après l'accouchement. Caillot dans un endométriome : non rehaussé."},{"i":"signes-cles","t":"Signes clés","x":"Tumeur ovarienne + anomalies utérines (endomètre épaissi, adénomyose) : penser à des tumeurs endométrioïdes synchrones de l'ovaire et de l'utérus, ou à une tumeur ovarienne sécrétante (granulosa). Devant des tumeurs endométrioïdes de l'ovaire et de l'utérus : tumeurs synchrones, primitif utérin avec métastases ovariennes, ou primitif ovarien avec métastases utérines."},{"i":"pieges","t":"Pièges","x":"Aucun critère IRM ne distingue un carcinome endométrioïde d'un carcinome à cellules claires. La diffusion n'est pas interprétable dans un contenu en hypersignal T1 : juger le rehaussement sur les soustractions."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et évolution de l'endométriome, portion tissulaire (taille, signal, diffusion, courbe), endomètre, autres localisations d'endométriose, score O-RADS IRM."}]},{"t":"Tératome mature","n":"Tératome mature","u":"ovaire/teratome-mature.html","c":"Ovaire","b":"la graisse est pathognomonique du tératome. Douleur pelvienne aiguë + kyste dermoïde = torsion d'annexe jusqu'à preuve du contraire.","s":[{"i":"terrain","t":"Terrain","x":"Tumeur germinale la plus fréquente (95 % des tumeurs germinales), 20 % des tumeurs ovariennes. À tout âge, avec une prédominance chez la femme jeune."},{"i":"imagerie","t":"Imagerie","x":"Kystique ou mixte, rond, uniloculaire (88 %), unilatéral plus souvent que bilatéral (12 %), hétérogène. Composantes : protubérance de Rokitansky, graisse, calcifications et dents, phanères (portions hyperéchogènes). Protubérance de Rokitansky Hyperéchogène avec atténuation postérieure marquée. Taille < 4 cm, ronde, angles de raccordement aigus avec la paroi. Graisse Échographie : échogénicité variable, de hypo- (sébum pur) à hyperéchogène (sébum + phanères), niveau liquidien possible, atténuation postérieure variable. IRM : hypersignal T1 ≥ graisse, qui chute en T1 FS. Scanner : densité graisseuse négative."},{"i":"complications","t":"Complications","x":"Torsion d'annexe (3 à 16 %). Rupture (1 à 4 %) : péritonite chimique granulomateuse avec implants péritonéaux. Transformation maligne (0,2 à 4 %) : protubérance de Rokitansky irrégulière, > 5 cm, à angles de raccordement obtus, épaississement pariétal localisé. Surinfection (exceptionnelle). Auto-immunité : anémie hémolytique, encéphalite à anticorps anti-NMDA."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kystes à contenu échogène : kyste lutéal hémorragique, endométriome (hypersignal T1 qui persiste en FS), abcès tubo-ovarien. Tératome immature : portion tissulaire prédominante, graisse en petites plages, nombreuses calcifications fines."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Prise en charge chirurgicale le plus souvent au-delà de 4 cm, du fait du risque de torsion. S'il n'est pas opéré : contrôle échographique à 12 mois (O-RADS 2 si < 10 cm)."},{"i":"pieges","t":"Pièges","x":"Une protubérance de Rokitansky peu rehaussée ne fait pas passer en O-RADS IRM 4 ; il faut une portion tissulaire volumineuse. Un petit kyste dermoïde très hyperéchogène peut se confondre avec le gaz digestif (« pointe de l'iceberg »)."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, bilatéralité, signes de complication (torsion, transformation maligne, rupture), parenchyme ovarien sain restant (fertilité ultérieure)."}]},{"t":"Tératome immature et goitre ovarien","n":"Tératome immature et goitre ovarien","u":"ovaire/teratome-immature-goitre-ovarien.html","c":"Ovaire","b":"deux tératomes rares. Le tératome immature est malin et à prédominance tissulaire chez la jeune fille ; le goitre ovarien est bénin, reconnaissable à son contenu colloïde.","s":[{"i":"teratome-immature","t":"Tératome immature","x":"Définition : tératome malin fait de dérivés immatures des trois feuillets embryonnaires. Terrain : jeune fille de moins de 20 ans ; 1 % des tumeurs ovariennes, 3 % des tumeurs germinales. Volumineux (> 10 cm), hétérogène, mixte, à prédominance solide ou kystique. Portion tissulaire microkystique en signal T2 intermédiaire, rehaussement tardif (courbe de type 2 ou 3, non discriminante). Graisse en fines plages (< 1 cm), calcifications nombreuses et fines. Kyste dermoïde associé sur le même ovaire (26 %) ou l'ovaire controlatéral (10 %). Rupture : implants péritonéaux graisseux et/ou calcifiés, gliomatose péritonéale secondaire."},{"i":"goitre-ovarien","t":"Goitre ovarien","x":"Définition : tératome monodermique bénin, à composante thyroïdienne prédominante ou quasi exclusive. Rare : 2 % des tumeurs germinales. Masse à prédominance kystique ou mixte, multiloculaire, loculi de signaux différents. Contenu colloïde, pathognomonique : iso- ou hypersignal T1, hyposignal T2 franc, pas de rehaussement. Cloisons épaisses et/ou nodule tissulaire : signal T2 intermédiaire, hypersignal diffusion, courbe de type 3 (tissu thyroïdien). Kyste dermoïde associé fréquent."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste dermoïde : graisse abondante, protubérance de Rokitansky < 4 cm, peu de portion tissulaire. Tumeur mucineuse : loculi de signaux différents, sans contenu colloïde en hyposignal T2 franc."},{"i":"pieges","t":"Pièges","x":"Le goitre ovarien a une courbe de type 3 alors qu'il est bénin. Une masse surtout tissulaire avec quelques petites plages de graisse chez une jeune fille ne doit pas être prise pour un kyste dermoïde."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, proportion de portion tissulaire, graisse (abondance, répartition), calcifications, loculi colloïdes, implants péritonéaux."}]},{"t":"Tumeurs germinales malignes non tératomateuses","n":"Germinales malignes","u":"ovaire/germinales-malignes.html","c":"Ovaire","b":"masse ovarienne complexe + jeune fille ou adolescente + élévation des marqueurs = tumeur germinale non tératomateuse. L'imagerie est peu spécifique, le contexte clinico-biologique oriente.","s":[{"i":"terrain","t":"Terrain","x":"Rares, malignes, chez la femme jeune. 60 % des tumeurs ovariennes de la jeune fille sont des tumeurs germinales (tous types confondus)."},{"i":"imagerie","t":"Imagerie","x":"Unilatérales, volumineuses, mixtes ou solides. Hétérogènes : cloisons ou travées hypervascularisées, remaniements nécrotico-hémorragiques possibles."},{"i":"marqueurs-et-types","t":"Marqueurs et types","x":"Tumeur · Marqueur · Particularités Dysgerminome · LDH · La plus fréquente ; femme de 20 à 30 ans ; solide pure, signal T2 intermédiaire, volumineuse (> 10 cm), contours polylobés, cloisons internes hypervascularisées Tumeur du sac vitellin · αFP · Masse mixte, hétérogène Carcinome embryonnaire · αFP ou hCG · Masse mixte peu spécifique Choriocarcinome non gestationnel · hCG · Remaniements hémorragiques"},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Tératome immature : graisse en petites plages et calcifications fines. Tumeur de la granulosa juvénile : signes d'hyperœstrogénie (pseudopuberté précoce). Lymphome : masse solide homogène, souvent bilatérale, adénopathies."},{"i":"pieges","t":"Pièges","x":"Toujours doser les marqueurs (αFP, hCG, LDH) devant une masse ovarienne solide de l'adolescente. Une hCG élevée oriente aussi vers une grossesse : l'éliminer d'abord."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, composantes solide et kystique, cloisons vascularisées, nécrose ou hémorragie, ascite, adénopathies, carcinose."}]},{"t":"Fibrome et fibrothécome","n":"Fibrome et fibrothécome","u":"ovaire/fibrome-fibrothecome.html","c":"Ovaire","b":"masse solide pure, bien limitée, en hyposignal T2 franc et hyposignal diffusion, avec une courbe de type 1 : c'est un fibrome, bénin.","s":[{"i":"terrain","t":"Terrain","x":"Tumeur des cordons sexuels et du stroma la plus fréquente (50 %), en périménopause. Le thécome peut sécréter des œstrogènes : endomètre épaissi, métrorragies."},{"i":"imagerie","t":"Imagerie","x":"Masse solide pure, unilatérale (90 %), ronde ou ovale, bien limitée, contours lobulés, parfois exophytique. Échographie : aspect variable, souvent hypoéchogène avec atténuation postérieure. IRM : hyposignal T2 franc, hyposignal diffusion, courbe de type 1. Lame d'épanchement péritonéal fréquente (50 à 70 %)."},{"i":"remaniements-possibles","t":"Remaniements possibles","x":"Remaniement · Signal Œdémateux · T2 intermédiaire, courbe de type 1 Kystique · Hypersignal T2, hyposignal T1 Hémorragique · T2 variable, hypersignal T1 Calcifié · Hyposignal T2 et T1 Myxoïde · Hypersignal T2, hyposignal T1, rehaussement Fibrome cellulaire · T2 intermédiaire, courbe de type 2 (ou 3) ; risque de récidive après exérèse"},{"i":"complications","t":"Complications","x":"Torsion d'annexe. Syndrome de Demons-Meigs : ascite + épanchement pleural qui régressent après exérèse."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome sous-séreux pédiculé : raccordé au myomètre, encorbellement vasculaire, autres myomes. Tumeur de Brenner : petite, calcifications centrales, courbe de type 2. Fibromatose ovarienne : plages mal limitées autour des follicules, pas de masse. Masses solides bilatérales : courbe de type 1 → fibromes bilatéraux (10 %) ; courbe de type 2 → métastases (sein, estomac, endomètre, lymphome)."},{"i":"pieges","t":"Pièges","x":"Un fibrome remanié ou cellulaire perd son hyposignal T2 franc : la courbe aide. Ascite + épanchement pleural + masse ovarienne ne signent pas toujours un cancer : penser au syndrome de Demons-Meigs. Fibromes bilatéraux et calcifiés chez une femme jeune : penser au syndrome de Gorlin."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, latéralité, signal T2, diffusion, type de courbe, remaniements, épanchement, endomètre (si thécome suspecté), score O-RADS IRM."}]},{"t":"Tumeurs des cordons sexuels","n":"Cordons sexuels","u":"ovaire/cordons-sexuels.html","c":"Ovaire","b":"devant une lésion ovarienne à prédominance solide, chercher les signes d'hypersécrétion. L'imprégnation œstrogénique oriente vers la granulosa ou le thécome, la virilisation vers la tumeur de Sertoli-Leydig.","s":[{"i":"terrain","t":"Terrain","x":"Troisième groupe de tumeurs ovariennes primitives (environ 8 %), souvent sécrétantes. Masses mixtes ou solides pures, polymorphes."},{"i":"signes-d-hypersecretion","t":"Signes d'hypersécrétion","x":"Imprégnation œstrogénique · Hyperandrogénie (virilisation) Pseudopuberté précoce, métrorragies, épaississement endométrial, adénomyose interne · Hypertrophie clitoridienne, aménorrhée ou spanioménorrhée, hirsutisme, acné, atrophie mammaire, raucité de la voix Tumeur de la granulosa, thécome · Tumeur de Sertoli-Leydig, tumeur à cellules stéroïdes"},{"i":"tumeurs","t":"Tumeurs","x":"Tumeur · Terrain et biologie · Imagerie Tumeur de la granulosa, forme adulte (95 %) · Périménopause ; métrorragies post-ménopausiques ; sécrétion d'œstrogènes (80 %), inhibine B · Solide, mixte ou à prédominance kystique, unilatérale, environ 10 cm, composante hémorragique, courbe de type 2 ou 3, hypertrophie du pédicule lombo-ovarien homolatéral Tumeur de la granulosa, forme juvénile (5 %) · Avant la puberté et avant 30 ans ; pseudopuberté précoce · Même aspect Tumeur de Sertoli-Leydig · Femme < 30 ans (75 %) ; virilisation ; testostérone et Δ4-androstènedione élevées si sécrétante (30 %) · Solide, mixte ou kystique, unilatérale (95 %), < 10 cm, ronde, bien limitée, portion solide en signal T2 intermédiaire, courbe de type 2 (ou 3) Tumeur stromale sclérosante · Bénigne, femme < 30 ans (82 %) · Solide ou mixte, unilatérale, < 10 cm, bien limitée, capsule en hyposignal T2, hypervascularisation périphérique annulaire au Doppler, rehaussement annulaire centripète (courbe de type 3) Tumeur à cellules stéroïdes · Rare ; androgènes surtout · Masse solide, peu spécifique"},{"i":"complications","t":"Complications","x":"Tumeur de la granulosa : rupture avec hémopéritoine."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Fibrome et fibrothécome : hyposignal T2 franc, courbe de type 1. Métastases solides : bilatérales, contexte de cancer connu. Hyperthécose et hyperplasie stromale : bilatérales, sans masse focale."},{"i":"pieges","t":"Pièges","x":"Une courbe de type 3 n'est pas toujours maligne : tumeur stromale sclérosante. Toujours regarder l'endomètre et le myomètre devant une masse ovarienne solide : leur épaississement trahit une sécrétion d'œstrogènes."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, composantes solide et kystique, hémorragie, signal T2, diffusion, courbe, pédicule ovarien, endomètre, hémopéritoine."}]},{"t":"Métastases ovariennes","n":"Métastases","u":"ovaire/metastases.html","c":"Ovaire","b":"des lésions ovariennes bilatérales, solides ou mixtes, doivent faire évoquer des métastases et chercher un cancer primitif, digestif ou mammaire.","s":[{"i":"terrain","t":"Terrain","x":"Environ 5 % des tumeurs ovariennes ; contexte oncologique connu dans deux tiers des cas. Dissémination hématogène, lymphatique ou péritonéale."},{"i":"imagerie","t":"Imagerie","x":"Bilatérales (60 à 80 %), parfois multifocales. Intra-ovariennes ou en implants de surface ; parenchyme ovarien sain adjacent parfois préservé. Œdème ovarien possible (infiltration lymphatique). Forme · Primitifs principaux · Aspect À prédominance solide · Sein, estomac, endomètre, lymphome · Signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 À prédominance kystique · Côlon, sein, appendice, col, endomètre · Kystique multiloculaire ou mixte, courbe de type 2 La tumeur de Krukenberg désigne une métastase ovarienne à cellules en bague à chaton, le plus souvent d'origine gastrique."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Cystadénocarcinome séreux bilatéral : carcinose fréquente, pas de primitif extra-ovarien. Tumeur mucineuse primitive : unilatérale dans 95 % des cas. Fibromes bilatéraux : hyposignal T2 franc, hyposignal diffusion, courbe de type 1. Hyperplasie stromale : épaississement cortical bilatéral en hyposignal T2, sans hypersignal diffusion."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Scanner thoraco-abdomino-pelvien, endoscopies digestives, examen et imagerie des seins selon le contexte."},{"i":"pieges","t":"Pièges","x":"Une tumeur mucineuse bilatérale est une métastase d'origine digestive jusqu'à preuve du contraire. Œdème ovarien massif bilatéral : penser à une infiltration métastatique, surtout gastrique."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Bilatéralité, taille, composantes solide et kystique, signal T2, diffusion, courbe, carcinose, adénopathies, recherche d'un primitif."}]}];
